import sys

args = sys.argv[1:]
num = "-n" in args
names = [a for a in args if a != "-n"]
out = sys.stdout.buffer
status = 0
n = 0


def emit(data):
    global n
    if not num:
        out.write(data)
        return
    if not data:
        return
    parts = data.split(b"\n")
    if parts[-1] == b"":
        parts.pop()
        lines = [p + b"\n" for p in parts]
    else:
        lines = [p + b"\n" for p in parts]
    for line in lines:
        n += 1
        if not line.endswith(b"\n"):
            line += b"\n"
        out.write(b"%6d\t" % n + line)


if not names:
    emit(sys.stdin.buffer.read())
else:
    for name in names:
        try:
            with open(name, "rb") as f:
                data = f.read()
        except OSError:
            out.write(("cat: %s: No such file\n" % name).encode())
            status = 1
            continue
        emit(data)
out.flush()
sys.exit(status)
